"""Revision 3: a focused systems-engineering identity, bilingual by design."""
def system(en=False):
 t= ['BUSINESS CONTEXT','Data · Tools · Quality standards','01 / EXECUTION','Task','Run','Check','Deliver / Review','02 / IMPROVEMENT','Feedback','Candidate','Evaluate','Release gate','A tested change returns to the execution loop.','Conceptual architecture · Not a live system'] if en else ['业务上下文','资料 · 工具 · 质量标准','01 / 任务执行','任务','执行','检查','交付 / 复核','02 / 受控改进','反馈','候选','评测','发布闸门','经过验证的变更，才回到执行环。','架构示意 · 非实时系统']
 return f'''<figure class="system-map"><figcaption><span>HL / SYSTEM DESIGN</span><span>↗</span></figcaption><div class="context-bar"><small>{t[0]}</small><p>{t[1]}</p></div><div class="loop-row"><h3>{t[2]}</h3><div class="nodes"><span>{t[3]}</span><i>→</i><span>{t[4]}</span><i>→</i><span>{t[5]}</span></div><p class="loop-exit">→ {t[6]}</p></div><div class="loop-row improvement"><h3>{t[7]}</h3><div class="nodes"><span>{t[8]}</span><i>→</i><span>{t[9]}</span><i>→</i><span>{t[10]}</span></div><p class="gate">↗ {t[11]}</p></div><p class="return-line">↑ {t[12]}</p><small class="system-caption">{t[13]}</small></figure>'''
def homepage(en=False):
 if en:
  return ('Custom harnesses. Measured evolution.', '''<div class="wrap"><div class="hero"><div class="hero-copy"><span class="eyebrow">CUSTOM HARNESSES / CONTROLLED EVOLUTION</span><h1>Built for your work.<br><em>Designed to evolve.</em></h1><p class="lead">We build the system around your AI: the context, tools and quality standards that make it useful. Then turn operational feedback into tested improvements.</p><div class="actions"><a class="btn" href="/contact/">Discuss your workflow <span>↗</span></a><a class="textlink" href="/how-it-works/">Explore the approach</a></div><p class="hero-note">Your business sets the standard.<br>Evidence decides what changes.</p></div>'''+system(True)+'''</div></div><section class="definition"><div class="wrap definition-grid"><span class="eyebrow">01 / THE WORK AROUND THE MODEL</span><div><h2>A model gives you capability.<br>A harness makes it fit.</h2><p>Different data. Different tools. Different definitions of “right”. We design these into a working system, rather than asking your business to adapt to a generic agent.</p><a class="textlink" href="/how-it-works/">What goes into a harness</a></div></div></section><section class="wrap"><div class="sectionhead"><div><span class="eyebrow">02 / WHERE WE START</span><h2>Work worth getting right.</h2></div><p>Start with a repeatable, data-intensive task whose outcome a person can evaluate.</p></div><div class="service-row"><span class="service-index">A</span><div><h3>Documents into usable data</h3><p>Extract records, preserve their sources and surface missing or contradictory information.</p></div><a href="/data-factory/" class="textlink">Explore the data factory →</a></div><div class="service-row"><span class="service-index">B</span><div><h3>Knowledge into a working process</h3><p>Bring authorized reference material and tools into a workflow with explicit review points.</p></div><span class="service-status">Scoping direction</span></div><div class="service-row"><span class="service-index">C</span><div><h3>Corrections into better versions</h3><p>Capture recurring failures, test proposed changes and retain a way back.</p></div><a href="/how-it-works/" class="textlink">See the improvement loop →</a></div></section><section class="light"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow">03 / A SMALL EXAMPLE</span><h2>A correction is not yet<br>an improvement.</h2></div><p>Synthetic procurement example. These are illustrative steps, not a live run or a measured customer result.</p></div><div class="evidence-path"><div><small>01 · SOURCE</small><h3>15 business days</h3><p>The document specifies a unit.</p></div><div><small>02 · FAILURE</small><h3><s>15 days</s></h3><p>The extraction loses that qualifier.</p></div><div><small>03 · CANDIDATE</small><h3>Preserve the unit</h3><p>A proposed rule addresses this error.</p></div><div><small>04 · DECISION</small><h3>Test before release</h3><p>Check independent samples and regressions.</p></div></div><a class="textlink" href="/data-factory/">Walk through the example →</a></div></section><section class="wrap delivery"><div><span class="eyebrow">04 / A FOCUSED PILOT</span><h2>One task.<br>A clear way to judge it.</h2><p class="lead">Define the job and acceptance criteria first. Use the pilot to decide what deserves to scale.</p></div><div class="deliverables"><div><span>01</span><h3>A task-specific workflow</h3><p>Inputs, tools, permissions and human review points.</p></div><div><span>02</span><h3>An evaluation baseline</h3><p>Representative samples, failure categories and checks.</p></div><div><span>03</span><h3>A version improvement plan</h3><p>Candidate tests, release decisions and rollback boundaries.</p></div><p class="micro">Proposed deliverables. Final scope depends on the assessed scenario and agreement.</p></div></section>''')
 return ('为业务定制，可验证地进化', '''<div class="wrap"><div class="hero"><div class="hero-copy"><span class="eyebrow">定制 HARNESS / 受控进化</span><h1>适配你的业务。<br><em>不止于第一次运行。</em></h1><p class="lead">我们为数据与知识密集型业务定制 Harness，连接资料、工具与质量标准，把运行中的反馈，转化为经过验证的版本改进。</p><div class="actions"><a class="btn" href="/contact/">讨论你的业务场景 <span>↗</span></a><a class="textlink" href="/how-it-works/">了解工作原理</a></div><p class="hero-note">业务决定什么是好结果。<br>证据决定下一版改什么。</p></div>'''+system()+'''</div></div><section class="definition"><div class="wrap definition-grid"><span class="eyebrow">01 / 模型之外的工作</span><div><h2>模型提供能力。<br>Harness 让能力适配业务。</h2><p>不同的资料，不同的工具，不同的“做对了”。我们把这些差异设计进执行系统，而不是让业务迁就一个通用智能体。</p><a class="textlink" href="/how-it-works/">一个 Harness 由什么组成</a></div></div></section><section class="wrap"><div class="sectionhead"><div><span class="eyebrow">02 / 从这里开始</span><h2>值得认真做好的工作。</h2></div><p>优先选择重复发生、依赖数据，并且能由人判断结果好坏的任务。</p></div><div class="service-row"><span class="service-index">A</span><div><h3>从复杂资料，到可用数据</h3><p>提取记录，保留来源，标出缺失与矛盾，让后续业务有据可查。</p></div><a href="/data-factory/" class="textlink">探索数据工厂 →</a></div><div class="service-row"><span class="service-index">B</span><div><h3>从业务知识，到执行流程</h3><p>将授权资料与工具接入工作流，在关键节点保留明确的人工判断。</p></div><span class="service-status">可共同评估的方向</span></div><div class="service-row"><span class="service-index">C</span><div><h3>从反复修正，到版本改进</h3><p>留下常见失败，验证候选变更，并为正式版本保留回退路径。</p></div><a href="/how-it-works/" class="textlink">了解改进机制 →</a></div></section><section class="light"><div class="wrap"><div class="sectionhead"><div><span class="eyebrow">03 / 一个小例子</span><h2>修正一个答案，<br>还不等于改进了系统。</h2></div><p>合成采购示例。以下展示设计步骤，不是实时运行，也不代表已验证的客户成果。</p></div><div class="evidence-path"><div><small>01 · 原文</small><h3>15 个工作日</h3><p>资料里明确写出了时间单位。</p></div><div><small>02 · 失败</small><h3><s>15 天</s></h3><p>提取结果丢失了关键限定。</p></div><div><small>03 · 候选</small><h3>保留原始单位</h3><p>提出针对该错误的规则变更。</p></div><div><small>04 · 决策</small><h3>验证后再发布</h3><p>检查独立样本，也检查退化。</p></div></div><a class="textlink" href="/data-factory/">逐步查看这个例子 →</a></div></section><section class="wrap delivery"><div><span class="eyebrow">04 / 聚焦的试点</span><h2>先做好一件事。<br>也知道怎样判断它。</h2><p class="lead">先明确任务与验收标准，再用试点结果，决定哪些能力值得扩大。</p></div><div class="deliverables"><div><span>01</span><h3>业务专属工作流</h3><p>输入、工具、权限，以及人工复核节点。</p></div><div><span>02</span><h3>一套评测基线</h3><p>代表性样本、失败分类与检查方法。</p></div><div><span>03</span><h3>版本改进方案</h3><p>候选测试、发布决策与回退边界。</p></div><p class="micro">以上为试点交付方向，具体范围以场景评估与合作约定为准。</p></div></section>''')

def enhance(pages, en=False):
 pages['']=homepage(en)
 title,body=pages['contact']
 old='This page creates a brief in your browser. It does not send or save it. A contact channel will be added once confirmed.'
 # Remove obsolete placeholder regardless of original English wording.
 import re
 if en:
  body=re.sub(r'<p>[^<]*(?:contact channel|contact route|contact method)[^<]*</p>','<p>Generate a brief here, then copy it into your email. This form does not send or save your input.</p>',body,flags=re.I)
  block='<div class="contact-address"><span class="eyebrow">START A CONVERSATION</span><a href="mailto:contact@harnessloop.ai">contact@harnessloop.ai <span>↗</span></a><p>Tell us what the task is, where it breaks down and what a good result looks like. Please use non-sensitive examples.</p></div>'
 else:
  body=body.replace('本页仅在浏览器中生成简报，不发送、不保存。正式联系入口将在确认后接入。','先在这里整理需求，再复制到邮件中。本表单不发送、不保存输入内容。')
  block='<div class="contact-address"><span class="eyebrow">联系 HARNESSLOOP</span><a href="mailto:contact@harnessloop.ai">contact@harnessloop.ai <span>↗</span></a><p>告诉我们任务是什么、难在哪里，以及怎样才算做好。请只使用不含敏感信息的示例。</p></div>'
 body=body.replace('<section class="wrap two"', '<div class="wrap">'+block+'</div><section class="wrap two"',1)
 body=body.replace('<p id="copy-status"', '<a class="textlink brief-email" id="email-brief" href="mailto:contact@harnessloop.ai">'+('Open email app' if en else '打开邮件客户端')+'</a><p class="micro">'+('You review and send the email yourself. Opening your email app does not send it.' if en else '由你检查并发送邮件。打开邮件客户端不会自动发送。')+'</p><p id="copy-status"')
 pages['contact']=(title,body)
 title,body=pages['data-factory']
 body=body.replace('id="demo-output" aria-live="polite"','id="demo-output" role="tabpanel" aria-labelledby="stage-0" aria-live="polite" tabindex="0"')
 for i in range(3):
  body=body.replace(f'data-stage="{i}"', f'data-stage="{i}" id="stage-{i}" aria-controls="demo-output" tabindex="{0 if i==0 else -1}"')
 pages['data-factory']=(title,body)
